// Clear deviceCallback_ to avoid use-after-free when the cached sink is reused:
// the callback lambda captures destroyed HpaeOutputCluster::this.
deviceCallback_ = nullptr;

InitPrimarySink();
ASSERT_TRUE(primarySink_ && primarySink_->IsInited());
if (!primarySinkInited_) {
    bool callbackInvoked = false;
    primarySink_->RegisterCurrentDeviceCallback(
        [&callbackInvoked](bool state) { callbackInvoked = true; });

CHECK_AND_RETURN_LOG(outputCluster_ != nullptr,
    "outputCluster_ is nullptr, sessionId %{public}u sceneType %{public}d, init/reload may have failed",
    sessionId, static_cast<int32_t>(sceneType));

// HpaeProcessCluster ctor builds mixer/effect nodes that need valid params
// (esp. channels); a default nodeInfo (channels=0) crashes in HpaeMixerNode.
nodeInfo.sceneType = HPAE_SCENE_DEFAULT;
nodeInfo.frameLen = sinkInfo.frameLen;
nodeInfo.samplingRate = sinkInfo.samplingRate;
nodeInfo.channels = sinkInfo.channels;
nodeInfo.format = sinkInfo.format;
